      intro: 'HTTP Live Streaming віддає відео як плейлист коротких сегментів на кількох рівнях якості, тож плеєр може швидко стартувати й перемикати рівні зі зміною з’єднання. Створити такий пакет вручну означає закодувати кожен варіант із вирівняними ключовими кадрами, сегментувати їх і записати головний плейлист, який правильно описує кожен варіант. Ця сторінка виконує всю роботу: вона перевіряє ваше завантаження, пропонує рівні драбини, які дозволяють ваше джерело й тариф, кодує кожен з них за допомогою libx264 і AAC у 2-секундні сегменти MPEG-TS, за бажанням додає субтитри з нашого власного транскрибувальника Whisper, спрайт розкадровки та I-frame-плейлист для перемотування й пакує все в tar.gz або zip, який можна розпакувати на будь-який статичний хост.',
