      privacyNote: 'Ваше завантаження йде з браузера в наше сховище й завантажується на наш власний GPU-сервер, де FFmpeg вирізає фрагмент, а шість моделей працюють як локальні процеси; жоден зовнішній постачальник ШІ не залучений, і ніщо не використовується для навчання. У кадри декодується лише вибраний фрагмент; решта джерела ніколи не обробляється. Вихідний об’єкт, робочі кадри, MP4 кожної моделі, збережені для переглядача порівняння, і архів результатів зареєстровано в реєстрі зберігання й видаляються, коли закінчується вікно, а посилання на архів спливає через 6 годин. Файли зберігаються 24 години для гостей; з безкоштовним обліковим записом ви обираєте строк від 24 годин до 2 років. Завдання реставрації не запускають автоматизований аналіз вмісту, який проходять стандартні конвертації.',
