      tagline: 'Очистьте, збільште й відреставруйте фото до вісьмома ШІ-моделями — попереднє очищення зі збереженням вірності (FBCNN, SCUNet, NAFNet), загальні апскейлери (Real-ESRGAN, SwinIR, HAT) і поліпшення облич (GFPGAN, CodeFormer) — і порівняйте кожен результат з оригіналом.',
