          body: 'Кадрування — повний кадр 0,96 мегапікселя, а його висота 800 пікселів перевищує 540, тож автоматичний масштаб обирає 2x. FBCNN працює першим у 1x, і його вивід стає робочим джерелом. Real-ESRGAN збільшує його до 4 800 x 3 200 за допомогою realesrgan-x4plus, потім ImageMagick зменшує до 50 відсотків фільтром Lanczos для PNG 2 400 x 1 600. GFPGAN працює на попередньо очищеному джерелі зі збільшенням 2, даючи ще один PNG 2 400 x 1 600 із реконструйованими обличчями й просто зміненою в розмірі решток. Це три виводи з дозволених 12. За власними оцінками сервера на мегапіксель час моделей — близько 0,96 x (3 + 2 + 6), приблизно 11 секунд, плюс кілька секунд підготовки й пакування; очікування єдиного слота реставрації може додати ще. Одне завдання витрачає одне ШІ-завдання з ліміту ШІ-завдань.',
