      whenNotToUse: 'Не використовуйте поліпшення облич для ідентифікації: GFPGAN і CodeFormer малюють правдоподібні обличчя з навченого апріорного розподілу, тож реконструйоване обличчя — щонайбільше зачіпка й ніколи не доказ того, хто був на знімку. Пропустіть інструмент для зображень, які вже великі й чіткі, де прохід 2x переважно додає текстуру GAN, і для фотографій більших за 12 000 пікселів із боку, які відхиляються. Якщо вам потрібна лише більша копія чистого зображення без попереднього очищення, моделей облич чи сітки порівняння, ШІ-збільшення зображення дешевше за часом. А якщо ваше пошкодження — розфокусування, а не розмиття руху, ваги GoPro NAFNet — не та модель для цього.',
