        'Співакам корисніше репетирувати під справжнє аранжування, ніж під MIDI-наближення.',
        'Повернення стему у вхідному форматі зберігає файл розміру для телефона розміром для телефона; MP3 на 10 МБ не має випадково стати завантаженням на 50 МБ.',
