      privacyNote: 'Ваша пісня зберігається в папці свого завдання й передається Demucs на нашому власному GPU, який записує вокальний і акомпанементний стеми в тимчасовий каталог; у ваше завантаження кодується лише акомпанемент, а тимчасовий каталог (включно з відкинутим вокальним стемом) видаляється після завершення завдання. Закодований інструментал зберігається із завданням. Аудіозавантаження також проходять етап автоматизованого аналізу на нашому сервері, який транскрибує файл за допомогою Whisper для внутрішньої перевірки, що зберігається із завданням. Жоден сторонній постачальник ШІ не залучений. Файли зберігаються 24 години для гостей; з безкоштовним обліковим записом ви обираєте строк від 24 годин до 2 років.',
